                    sharedPrefs.saveAppGroup(updated)
                    onSaved(updated)
                }
            ) {
                Text("Save")
            }
        },
        dismissButton = {
            TextButton(onClick = onDismiss) {
                Text("Cancel")
            }
        }
    )
}

@Composable
fun UninstallProtectionDialog(
    currentGroup: AppGroup,
    sharedPrefs: SharedPreferencesManager,
    activity: ComponentActivity,
    onDismiss: () -> Unit,
    onSaved: (AppGroup) -> Unit
) {
