        try {
            activity.packageManager.getApplicationIcon(currentGroup.app2PackageName)
        } catch (_: Exception) {
            null
        }
    }

    AlertDialog(
        onDismissRequest = onDismiss,
        containerColor = Color(0xFF03193B),
        title = {
            Text(
