            AuthType("PASSWORD", "Alphanumeric password", "PWD", iconResourceId = R.drawable.ic_pwd, enabled = true),
            AuthType("PATTERN", "Draw a pattern", "PAT", iconResourceId = R.drawable.ic_pat, enabled = true)
