            Text(
                text = "Note: You can add biometric unlock after this setup",
                fontSize = 12.sp,
                color = Color(0xFF7DB8DE),
                fontStyle = androidx.compose.ui.text.font.FontStyle.Italic,
                lineHeight = 16.sp,
                textAlign = androidx.compose.ui.text.style.TextAlign.Center
            )
        }
    }
}

data class AuthType(
