                .fillMaxSize()
                .padding(24.dp),
            enabled = true,
            hapticIntensity = hapticIntensity,
            onPatternDrawn = onPatternDrawn
        )
    }
}

@Composable
fun BiometricAppsSelectionDialog(
    app1Name: String,
    app2Name: String,
    app1Enabled: Boolean,
    app2Enabled: Boolean,
    onApp1Changed: (Boolean) -> Unit,
    onApp2Changed: (Boolean) -> Unit,
    onDismiss: () -> Unit,
    onConfirm: () -> Unit,
    app1Icon: android.graphics.drawable.Drawable? = null,
    app2Icon: android.graphics.drawable.Drawable? = null
) {
    var selectedApp by remember {
        mutableStateOf(when {
            app1Enabled -> "app1"
            app2Enabled -> "app2"
            else -> ""
        })
    }

    AlertDialog(
        onDismissRequest = onDismiss,
        containerColor = Color(0xFF03193B),
        title = {
            Text(
                text = "Biometric Unlock",
                fontWeight = FontWeight.Bold,
                color = Color.White
            )
        },
        text = {
            Column(verticalArrangement = Arrangement.spacedBy(12.dp)) {
                Text(
                    text = "Select one app to enable biometric unlock. The other app will use the backup authentication method.",
                    color = Color(0xFFB0B0B0),
                    fontSize = 12.sp
                )

                Spacer(modifier = Modifier.height(4.dp))

                // OFF Option
                Card(
                    modifier = Modifier
                        .fillMaxWidth()
                        .clickable {
                            selectedApp = ""
                            onApp1Changed(false)
                            onApp2Changed(false)
                        },
                    colors = CardDefaults.cardColors(
                        containerColor = if (selectedApp == "") Color(0xFF0F4A8F) else Color(0xFF0F2A54)
                    )
                ) {
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(12.dp),
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.SpaceBetween
                    ) {
                        Text(
                            text = "OFF",
                            fontSize = 14.sp,
                            color = Color.White,
                            fontWeight = FontWeight.Bold
                        )

                        Box(
                            modifier = Modifier
                                .size(24.dp)
                                .background(
                                    color = if (selectedApp == "") Color(0xFF5DADE2) else Color(0xFF546E7A),
                                    shape = RoundedCornerShape(4.dp)
                                ),
                            contentAlignment = Alignment.Center
                        ) {
                            if (selectedApp == "") {
                                Text("✓", color = Color.White, fontSize = 14.sp, fontWeight = FontWeight.Bold)
                            }
                        }
                    }
                }

                // App 1 Option
                Card(
                    modifier = Modifier
                        .fillMaxWidth()
                        .clickable {
                            selectedApp = "app1"
                            onApp1Changed(true)
                            onApp2Changed(false)
                        },
                    colors = CardDefaults.cardColors(
                        containerColor = if (selectedApp == "app1") Color(0xFF0F4A8F) else Color(0xFF0F2A54)
                    )
                ) {
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(12.dp),
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.SpaceBetween
                    ) {
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            modifier = Modifier.weight(1f)
                        ) {
                            if (app1Icon != null) {
                                Image(
                                    bitmap = app1Icon.toBitmap().asImageBitmap(),
                                    contentDescription = app1Name,
                                    modifier = Modifier
                                        .size(32.dp)
                                        .clip(RoundedCornerShape(6.dp))
                                )
                            }

                            Spacer(modifier = Modifier.width(12.dp))

                            Text(
                                text = app1Name,
                                fontSize = 14.sp,
                                color = Color.White,
                                fontWeight = FontWeight.SemiBold
                            )
                        }

                        Box(
                            modifier = Modifier
                                .size(24.dp)
                                .background(
                                    color = if (selectedApp == "app1") Color(0xFF5DADE2) else Color(0xFF546E7A),
                                    shape = RoundedCornerShape(4.dp)
                                ),
                            contentAlignment = Alignment.Center
                        ) {
                            if (selectedApp == "app1") {
                                Text("✓", color = Color.White, fontSize = 14.sp, fontWeight = FontWeight.Bold)
                            }
                        }
                    }
                }

                // App 2 Option
                Card(
                    modifier = Modifier
                        .fillMaxWidth()
                        .clickable {
                            selectedApp = "app2"
                            onApp1Changed(false)
                            onApp2Changed(true)
                        },
                    colors = CardDefaults.cardColors(
                        containerColor = if (selectedApp == "app2") Color(0xFF0F4A8F) else Color(0xFF0F2A54)
                    )
                ) {
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(12.dp),
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.SpaceBetween
                    ) {
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            modifier = Modifier.weight(1f)
                        ) {
                            if (app2Icon != null) {
                                Image(
                                    bitmap = app2Icon.toBitmap().asImageBitmap(),
                                    contentDescription = app2Name,
                                    modifier = Modifier
                                        .size(32.dp)
                                        .clip(RoundedCornerShape(6.dp))
                                )
                            }

                            Spacer(modifier = Modifier.width(12.dp))

                            Text(
                                text = app2Name,
                                fontSize = 14.sp,
                                color = Color.White,
                                fontWeight = FontWeight.SemiBold
                            )
                        }

                        Box(
                            modifier = Modifier
                                .size(24.dp)
                                .background(
                                    color = if (selectedApp == "app2") Color(0xFF5DADE2) else Color(0xFF546E7A),
                                    shape = RoundedCornerShape(4.dp)
                                ),
                            contentAlignment = Alignment.Center
                        ) {
                            if (selectedApp == "app2") {
                                Text("✓", color = Color.White, fontSize = 14.sp, fontWeight = FontWeight.Bold)
                            }
                        }
                    }
                }

                Spacer(modifier = Modifier.height(4.dp))

                Text(
                    text = "Policy: <Auth Type> + Biometric for selected app",
                    color = Color(0xFF7DB8DE),
                    fontSize = 11.sp,
                    fontStyle = androidx.compose.ui.text.font.FontStyle.Italic
                )
            }
        },
        confirmButton = {
            TextButton(
                enabled = true,
                onClick = {
                    onConfirm()
                }
            ) {
                Text("Next")
            }
        },
        dismissButton = {
            TextButton(onClick = onDismiss) {
                Text("Cancel")
            }
        }
    )
}


@Composable
fun BiometricBackupCredentialDialog(
    groupName: String,
    onBackupTypeSelected: (String) -> Unit
) {
    AlertDialog(
        onDismissRequest = {},
        containerColor = Color(0xFF03193B),
        title = {
            Text(
                text = "Backup for $groupName",
                fontWeight = FontWeight.Bold,
                color = Color.White,
                fontSize = 14.sp
            )
        },
        text = {
            Column(verticalArrangement = Arrangement.spacedBy(10.dp)) {
                Text(
                    text = "Choose authentication method for this app:",
                    color = Color(0xFFB0B0B0),
                    fontSize = 12.sp
                )

                val backupTypes = listOf(
                    AuthType("PIN", "4 digit PIN", "PIN", enabled = true),
                    AuthType("PASSWORD", "Alphanumeric password", "PWD", enabled = true),
                    AuthType("PATTERN", "Draw a pattern", "PAT", enabled = true)
                )

                backupTypes.forEach { authType ->
                    AuthenticationTypeSelectionCard(
                        authType = authType,
                        onSelected = { onBackupTypeSelected(authType.name) }
                    )
                }
            }
        },
        confirmButton = {}
    )
}

